package dev.eugheist.tc4modern;
import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceKey;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.*;import net.minecraft.world.entity.player.Player;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import thaumcraft.api.aspects.*;
/** EventHandlerEntity's haste acceleration and 40-tick vis repair, using modern enchantment holders. */
@EventBusSubscriber(modid=TC4Modern.MODID)
public final class BasicsEnchantments {
 public static final ResourceKey<Enchantment> HASTE=ResourceKey.create(Registries.ENCHANTMENT,AlchemyContent.id("haste")),REPAIR=ResourceKey.create(Registries.ENCHANTMENT,AlchemyContent.id("repair"));
 static int level(Player p,ItemStack s,ResourceKey<Enchantment> key){return EnchantmentHelper.getItemEnchantmentLevel(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(key),s);}
 public static boolean repair(Player p,ItemStack s){int n=Math.min(2,level(p,s,REPAIR));if(n<=0||!s.isDamaged()||!s.is(net.minecraft.tags.TagKey.create(Registries.ITEM,AlchemyContent.id("repairable"))))return false;var tags=DeconstructorEntity.tags(s,p.level());if(tags.size()==0)return false;var primal=thaumcraft.common.lib.research.ResearchManager.reduceToPrimals(tags);var cost=new AspectList();for(var a:primal.getAspects())cost.merge(a,(int)Math.sqrt(primal.getAmount(a)*2)*n);for(int i=p.getInventory().items.size()-1;i>=0;i--){var wand=p.getInventory().getItem(i);if(WandData.consumeCrafting(wand,cost,true,p)){s.setDamageValue(Math.max(0,s.getDamageValue()-n));p.getInventory().setChanged();return true;}}return false;}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.PlayerTickEvent.Post event){var p=event.getEntity();if(!p.level().isClientSide&&!p.getAbilities().instabuild&&p.tickCount%40==0){for(var s:p.getInventory().items)if(!s.is(HoverHarness.harness()))repair(p,s);for(var s:p.getInventory().armor)repair(p,s);}if(!p.getAbilities().flying&&p.zza>0){int haste=level(p,p.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.FEET),HASTE);if(haste>0){float bonus=haste*.015f;if(p.isInWater())bonus*=.5f;if(p.onClimbable())bonus*=.5f;p.moveRelative(bonus,new net.minecraft.world.phys.Vec3(0,0,1));}}}
}
